    /** Render an inline SVG icon. @param string $name icon name; @param string $extra extra classes */
    public static function get(string $name, string $extra = ''): string
    {
        if (self::$paths === []) self::load();
        $body = self::$paths[$name] ?? '<path d="M9 12h6M12 9v6"/><circle cx="12" cy="12" r="8.5"/>';
        $cls = 'ico' . ($extra !== '' ? ' ' . $extra : '');
        return '<svg class="' . e($cls) . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' . $body . '</svg>';
    }
}
/** Print an icon — same as EdunexIcons::get. */
function icon(string $name, string $extra = ''): string
{
    return EdunexIcons::get($name, $extra);
}
